import { Link, Navigate, useLocation, useNavigate } from 'react-router-dom';
import { LEVELS } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { PlaceHead } from '@/components/layout/PlaceHead.js';
import { t } from '@/i18n/index.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useKeepScroll } from '@/lib/useKeepScroll.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { loadToday, type TodayData } from '@/features/today/data.js';
import { getActiveNotebook, loadSchedule } from '@/db/repo.js';
import { SRS_OFF, loadSrsView } from '@/features/schedule/data.js';
import { learnShows } from '@/features/learn/state.js';
import { GAMES_PATH } from '@/features/modes/data.js';
import { useOpenModes } from '@/features/modes/useOpenModes.js';
import { LEGACY_GAMES_HASH } from '@/lib/platform/appLink.js';
import styles from './Decks.module.css';

const EMPTY = { topics: [], levels: [], kinds: [], counts: { total: 0 } } as unknown as TodayData;

/**
 * Decks, or the games screen for somebody who followed an old link to the
 * games' place on it. The games were a section of this screen that Today's
 * "Games and drills" opened at `/decks#games` until 2026-10-09, and that
 * address must keep working because older builds still link to it: Android
 * 1.0.51, desktop 0.3.0, the landing site and Today tiles held by an older
 * service worker. It is replaced, not pushed, so Back goes to wherever the
 * learner came from.
 */
export function Decks(): React.JSX.Element {
  const { hash } = useLocation();
  if (hash === LEGACY_GAMES_HASH) return <Navigate to={GAMES_PATH} replace />;
  return <DecksScreen />;
}

/**
 * Decks: the whole notebook cut by level and by topic. The prototype keeps
 * these off Today and behind its "By topic or level" row, so Today stays a
 * single decision and this screen carries the browsing.
 */
function DecksScreen(): React.JSX.Element {
  const navigate = useNavigate();
  const now = useCurrentDay();
  const data = useLiveQuery(() => loadToday(now), EMPTY, [now]);
  // SRS v2: every deck here is extra practice, and when the notebook keeps
  // extra practice out of the schedule the screen says so before a tap.
  const srs = useLiveQuery(loadSrsView, SRS_OFF, []);
  const keepsBoxes = useLiveQuery(
    async () => {
      const [srs, notebook] = await Promise.all([loadSrsView(), getActiveNotebook()]);
      if (!srs.enabled || notebook === undefined) return false;
      return (await loadSchedule(notebook.id)).extraPractice === 'keep';
    },
    false,
    [],
  );

  // SRS v2: a quiet way across to the games, only while one can run here.
  const { open: games } = useOpenModes();

  // Back from a word, a deck or a page lands where the reader was.
  useKeepScroll();
  const biggest = Math.max(...data.topics.map((topic) => topic.count), 1);

  const byLevel = new Map(data.levels.map((entry) => [entry.level, entry.count]));

  return (
    <main className={styles.screen}>
      <PlaceHead title={t('decks.title')} />
      {games.length > 0 && (
        <Link to={GAMES_PATH} className={styles.gamesLink}>
          <span className={styles.gamesIcon} aria-hidden="true">
            <Icon name="grid" size={16} weight={1.9} />
          </span>
          <span className={styles.gamesName}>{t('decks.games')}</span>
          <span className={styles.gamesNote}>{t('today.gamesShort', { count: games.length })}</span>
          <Icon name="chevronRight" size={16} weight={2} className={styles.gamesGo} />
        </Link>
      )}
      {/* With the new learner's journey, in plain words, and only when it
          is true of something here: a word that is not due yet (M7, C5). */}
      {keepsBoxes &&
        (learnShows(srs) ? (
          data.notDue && <p className={styles.deckLine}>{t('decks.extraLine')}</p>
        ) : (
          <p className={styles.deckLine}>{t('schedule.deckLine')}</p>
        ))}

      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>{t('decks.byLevel')}</h2>
        <div className={styles.levels}>
          {LEVELS.map((level) => {
            const count = byLevel.get(level) ?? 0;
            return (
              <button
                key={level}
                type="button"
                className={styles.level}
                disabled={count === 0}
                onClick={() => {
                  void navigate(`/session?deck=level&level=${level}`);
                }}
              >
                <span className={styles.levelName}>{level}</span>
                <span className={styles.levelCount}>{count}</span>
              </button>
            );
          })}
        </div>
      </section>

      {data.kinds.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('decks.byKind')}</h2>
          <div className={styles.kinds}>
            {data.kinds.map((entry) => (
              <button
                key={entry.kind}
                type="button"
                className={styles.level}
                onClick={() => {
                  void navigate(`/session?deck=kind&kind=${entry.kind}`);
                }}
              >
                <span className={styles.kindName}>{t(`kind.${entry.kind}`)}</span>
                <span className={styles.levelCount}>{entry.count}</span>
              </button>
            ))}
          </div>
        </section>
      )}

      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>{t('decks.byTopic')}</h2>
        {data.topics.length === 0 ? (
          <EmptyState
            compact
            icon="grid"
            tone="quiet"
            title={t('decks.noTopicsTitle')}
            body={t('decks.noTopics')}
          />
        ) : (
          <div className={styles.topics}>
            {data.topics.map((topic) => (
              <button
                key={topic.name}
                type="button"
                className={styles.topic}
                onClick={() => {
                  void navigate(`/session?deck=topic&topic=${encodeURIComponent(topic.name)}`);
                }}
              >
                <span className={styles.topicName}>{topic.name.replace(/-/g, ' ')}</span>
                <span className={styles.topicMeta}>
                  <span className={styles.topicCount}>{topic.count}</span>
                  <span className={styles.track}>
                    <span
                      className={styles.fill}
                      style={{ width: `${String(Math.round((topic.count / biggest) * 100))}%` }}
                    />
                  </span>
                </span>
              </button>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}
